PyObject* support(PyObject*,PyObject*args){namespace p=stock_native_bot_python;PyObject*descriptor,*raw;int attached;if(!PyArg_ParseTuple(args,"OOi",&descriptor,&raw,&attached))return nullptr;try{VehicleGeometry geometry;if(!readVehicleGeometry(descriptor,geometry))return nullptr;VehiclePose pose;pose.position=p::numbers<3>(p::value(raw,"position").get());pose.attitude=p::numbers<3>(p::value(raw,"attitude").get());pose.hull_position=p::numbers<3>(p::value(raw,"hull_position").get());pose.hull_attitude=p::numbers<3>(p::value(raw,"hull_attitude").get());pose.separate_hull=p::truth(raw,"separate");pose.aim_yaw=p::numeric(raw,"aim_yaw");pose.gun_pitch=p::numeric(raw,"gun_pitch");auto out=p::list();for(const auto&box:vehicleSupportBoxes(geometry,pose,attached!=0)){auto row=p::list(),axes=p::list();p::append(row.get(),p::numbers(box.center));for(const auto&a:box.axes)p::append(axes.get(),p::numbers(a));p::append(row.get(),axes);p::append(out.get(),row);}return out.release();}catch(const std::exception&e){if(!PyErr_Occurred())PyErr_SetString(PyExc_ValueError,e.what());return nullptr;}}
